async function exportVideo(mp4:boolean){
  const blocked=exportBlocker(promptInput.value,!!assets.original,!!assets.result);if(blocked){setStatus(blocked,true);return;}if(!('MediaRecorder'in window)||!preview.captureStream){setStatus('Video export is not supported in this browser. Try current Chrome or Edge.',true);return;}
  cancelExport=false;const buttons=[$('#export-video'),$('#export-webm')] as HTMLButtonElement[];buttons.forEach(button=>button.disabled=true);$('#cancel-export').disabled=false;$('#export-progress').classList.remove('hidden');$('#export-progress').value=0;$('#export-stage').textContent='Rendering the shared reel timeline…';setStatus('Rendering the same timeline used in the live preview. Keep this tab open.');let stream:MediaStream|null=null;
  try{
    const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(type=>MediaRecorder.isTypeSupported(type));if(!mime)throw Error('This browser does not provide a supported WebM recorder.');const output=document.createElement('canvas');output.width=REEL_EXPORT_SIZE.width;output.height=REEL_EXPORT_SIZE.height;render(0,output);stream=output.captureStream(24);
    const audioEnabled=!!audioFile&&($('#music-on') as HTMLInputElement).checked;if(audioEnabled){await initAudio();const player=$('#audio-player') as HTMLAudioElement,trim=audioTrim(),mixDuration=Math.min(duration,trim.duration),now=audioContext!.currentTime,volume=($('#music-mute') as HTMLInputElement).checked?0:inputValue('music-volume');if(trim.duration<=0)throw Error('Set the music trim end after its start.');const fadeIn=Math.min(inputValue('fade-in'),mixDuration/2),fadeOut=Math.min(inputValue('fade-out'),mixDuration-fadeIn);player.pause();player.currentTime=trim.start;audioGain!.gain.cancelScheduledValues(now);audioGain!.gain.setValueAtTime(0,now);if(fadeIn)audioGain!.gain.linearRampToValueAtTime(volume,now+fadeIn);else audioGain!.gain.setValueAtTime(volume,now);if(fadeOut){audioGain!.gain.setValueAtTime(volume,now+mixDuration-fadeOut);audioGain!.gain.linearRampToValueAtTime(0,now+mixDuration);}stream.addTrack(audioDestination!.stream.getAudioTracks()[0]);await player.play().catch(()=>{throw Error('Browser blocked music playback. Press Preview trim once and retry export.');});}
    const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6_000_000});currentRecorder=recorder;const chunks:BlobPart[]=[];let size=0;recorder.ondataavailable=event=>{if(event.data.size){size+=event.data.size;if(size>250*1024*1024){cancelExport=true;recorder.stop();}else chunks.push(event.data);}};const done=new Promise<void>((resolve,reject)=>{recorder.onstop=()=>resolve();recorder.onerror=()=>reject(Error('Browser video recording failed.'));});const startedAt=performance.now();recorder.start(500);
    const draw=()=>{if(cancelExport){if(recorder.state==='recording')recorder.stop();return;}const elapsed=(performance.now()-startedAt)/1000;$('#export-progress').value=clamp(elapsed/duration)*.65;render(Math.min(duration,elapsed),output);if(elapsed<duration&&recorder.state==='recording')requestAnimationFrame(draw);else if(recorder.state==='recording')recorder.stop();};requestAnimationFrame(draw);await done;currentRecorder=null;if(cancelExport)throw Error('Export cancelled.');if(audioEnabled)($('#audio-player') as HTMLAudioElement).pause();const webm=new Blob(chunks,{type:mime});if(webm.size<1000)throw Error('The browser produced an empty recording.');
    if(!mp4){download(webm,'prompt-master-reel.webm');const result=await showExport(webm);$('#export-progress').value=1;$('#export-stage').textContent=`WebM ready · ${result.width} × ${result.height} · ${result.duration.toFixed(1)}s`;setStatus('WebM export decoded successfully.');return;}
    await loadEncoder();if(cancelExport)throw Error('Export cancelled.');$('#export-stage').textContent='Transcoding to H.264 / AAC MP4…';$('#export-progress').value=.68;await ffmpeg!.writeFile('prompt-master-input.webm',new Uint8Array(await webm.arrayBuffer()));const args=['-i','prompt-master-input.webm','-c:v','libx264','-preset','ultrafast','-crf','24','-pix_fmt','yuv420p','-r','24','-threads','1'];if(audioEnabled)args.push('-c:a','aac','-b:a','160k');args.push('-movflags','+faststart','prompt-master-output.mp4');const code=await ffmpeg!.exec(args);if(cancelExport)throw Error('Export cancelled.');if(code!==0)throw Error(`MP4 encoding failed (FFmpeg exit ${code}). Try WebM export or a shorter clip.`);const bytes=await ffmpeg!.readFile('prompt-master-output.mp4');if(typeof bytes==='string'||bytes.length<1000||String.fromCharCode(...bytes.slice(4,8))!=='ftyp')throw Error('Encoder output did not validate as MP4.');const blob=new Blob([bytes],{type:'video/mp4'});download(blob,'prompt-master-reel.mp4');const info=await showExport(blob);$('#export-progress').value=1;$('#export-stage').textContent=`MP4 ready · ${info.width} × ${info.height} · ${info.duration.toFixed(1)}s`;setStatus('MP4 export decoded successfully.');
  }catch(error){setStatus(error instanceof Error?error.message:'Video export failed. Try WebM or a shorter clip.',true);$('#export-stage').textContent='Export failed. You can retry or choose WebM.';}finally{if(ffmpeg?.loaded){await ffmpeg.deleteFile('prompt-master-input.webm').catch(()=>{});await ffmpeg.deleteFile('prompt-master-output.mp4').catch(()=>{});}currentRecorder=null;if(stream)stream.getTracks().forEach(track=>track.stop());if(audioFile)($('#audio-player') as HTMLAudioElement).pause();$('#cancel-export').disabled=true;buttons.forEach(button=>button.disabled=false);render(inputValue('duration-control'));}
}

promptInput.addEventListener('input',()=>{textStyles.prompt.text=promptInput.value;if(selectedText==='prompt')setEditorValue('text-content',promptInput.value);update();});$('#example').onclick=()=>{promptInput.value=example;textStyles.prompt.text=example;if(selectedText==='prompt')setEditorValue('text-content',example);update();};$('#clear-prompt').onclick=()=>{promptInput.value='';textStyles.prompt.text='';if(selectedText==='prompt')setEditorValue('text-content','');update();};
for(const kind of ['original','result','logo'] as AssetName[])setupImageInput(kind);
$('#intro-title-value').addEventListener('input',()=>{textStyles.introTitle.text=$('#intro-title-value').value;render(inputValue('duration-control'));});$('#prompt-number-value').addEventListener('input',()=>{textStyles.promptNumber.text=$('#prompt-number-value').value;render(inputValue('duration-control'));});$('#show-intro-title').onchange=()=>{textStyles.introTitle.visible=$('#show-intro-title').checked;if(selectedText==='introTitle')setEditorValue('text-visible',textStyles.introTitle.visible);render(inputValue('duration-control'));};$('#show-prompt-number').onchange=()=>{textStyles.promptNumber.visible=$('#show-prompt-number').checked;if(selectedText==='promptNumber')setEditorValue('text-visible',textStyles.promptNumber.visible);render(inputValue('duration-control'));};$('#prompt-id').addEventListener('input',()=>{if(($('#auto-prompt-number') as HTMLInputElement).checked){textStyles.promptNumber.text=promptNumberFromId($('#prompt-id').value);$('#prompt-number-value').value=textStyles.promptNumber.text;if(selectedText==='promptNumber')renderTextEditor();else render(inputValue('duration-control'));}});$('#auto-prompt-number').onchange=()=>{if($('#auto-prompt-number').checked){textStyles.promptNumber.text=promptNumberFromId($('#prompt-id').value);$('#prompt-number-value').value=textStyles.promptNumber.text;renderTextEditor();}};
$('#template').onchange=()=>applyTemplate(($('#template') as HTMLSelectElement).value);$('#reset-intro').onclick=resetIntro;$('#reset-all-text').onclick=()=>{if(!confirm('Reset every text element to its Prompt Master default?'))return;textStyles=createDefaultText();textStyles.promptNumber.text=promptNumberFromId($('#prompt-id').value);$('#intro-title-value').value=textStyles.introTitle.text;$('#prompt-number-value').value=textStyles.promptNumber.text;promptInput.value=textStyles.prompt.text;renderTextEditor();update();};$('#text-select').onchange=()=>{selectedText=($('#text-select') as HTMLSelectElement).value;renderTextEditor();};
$('#play').onclick=togglePlay;$('#restart').onclick=()=>{if(playing)togglePlay();$('#duration-control').value='0';render(0);};$('#preview-mute').onclick=()=>{const mute=$('#music-mute') as HTMLInputElement;mute.checked=!mute.checked;syncAudioControls();$('#preview-mute').textContent=mute.checked?'♩':'♪';};$('#duration-control').oninput=()=>{if(playing)togglePlay();render(inputValue('duration-control'));};$('#comparison-slider').oninput=()=>{if(playing)togglePlay();const trans=timeline().scenes.transition;const time=trans.start+inputValue('comparison-slider')/100*trans.duration;$('#duration-control').value=String(time);render(time);};
for(const node of document.querySelectorAll('input,select,textarea')){if(!(node instanceof HTMLElement)||['prompt','original-file','result-file','logo-file','music-file','text-content'].includes((node as HTMLInputElement).id))continue;node.addEventListener('input',()=>{if(node.id==='text-select')return;if(node.id==='music-volume')syncAudioControls();if(node.id==='intro-title-value')textStyles.introTitle.text=(node as HTMLInputElement).value;if(node.id==='prompt-number-value')textStyles.promptNumber.text=(node as HTMLInputElement).value;render(inputValue('duration-control'));update();});}
$('#preview-resolution').onchange=()=>{const width=inputValue('preview-resolution');preview.width=width;preview.height=Math.round(width*16/9);render(inputValue('duration-control'));};$('#export-video').onclick=()=>void exportVideo(true);$('#export-webm').onclick=()=>void exportVideo(false);$('#cancel-export').onclick=()=>{cancelExport=true;if(currentRecorder?.state==='recording')currentRecorder.stop();else if(ffmpeg){ffmpeg.terminate();ffmpeg=null;setStatus('Export cancelled.',true);}};
$('#save').onclick=save;$('#duplicate').onclick=async()=>{try{localStorage.setItem('prompt-master-duplicate',JSON.stringify(await projectForStorage()));setStatus('Project duplicated in local storage.');}catch{setStatus('Could not duplicate: browser storage is full.',true);}};$('#load').onclick=()=>{try{restoreProject(JSON.parse(localStorage.getItem('prompt-master-project')||'null'));setStatus('Recent project settings loaded. Re-select original/result photos and music if needed.');}catch{setStatus('No saved project found on this device.',true);}};$('#load-duplicate').onclick=()=>{try{restoreProject(JSON.parse(localStorage.getItem('prompt-master-duplicate')||'null'));setStatus('Duplicate project loaded. Re-select photos and music if needed.');}catch{setStatus('No duplicate project found.',true);}};$('#clear-storage').onclick=()=>{if(confirm('Clear locally saved Prompt Master projects?')){localStorage.removeItem('prompt-master-project');localStorage.removeItem('prompt-master-duplicate');setStatus('Saved project settings cleared.');}};$('#new').onclick=resetProject;$('#export-json').onclick=exportJSON;$('#import-json').onclick=()=>$('#json-file').click();$('#json-file').onchange=()=>{const file=($('#json-file') as HTMLInputElement).files?.[0];if(file)loadJSON(file);};
